import { PRODUCT_QUERY } from './product-queries';

export const RECOMMEND_PRODUCT_QUERY = `query ProductRecommendations(
  $productId: ID!,
  $intent: ProductRecommendationIntent,
  $country: CountryCode,
  $language: LanguageCode
) @inContext(country: $country, language: $language) {
  productRecommendations(productId: $productId, intent:$intent) {
    ...productQuery
  }
}${PRODUCT_QUERY}`;
