import { SIMPLE_MONEY } from './utility-queries';

export const VARIANT_QUERY = `fragment VariantQuery on ProductVariant {
  id
  title
  availableForSale
  price {
    ...SimpleMoney
  }
  compareAtPrice {
    ...SimpleMoney
  }
  selectedOptions {
    name
    value
  }
}`;

export const PRODUCT_QUERY = `fragment productQuery on Product {
  id
  title
  descriptionHtml
  handle
  availableForSale
  priceRange {
    minVariantPrice {
      ...SimpleMoney
    }
    maxVariantPrice {
      ...SimpleMoney
    }
  }
  compareAtPriceRange {
    minVariantPrice {
      ...SimpleMoney
    }
  }
  media(first: 1) {
    edges {
      node {
        ... on MediaImage {
          image {
            url
          }
        }
      }
    }
  }
  variants(first: 250) {
    edges {
      node {
        ...VariantQuery
      }
    }
  }
}
${SIMPLE_MONEY}${VARIANT_QUERY}`;
