import { RECOMMEND_PRODUCT_QUERY } from '../queries/recommendation-queries';
import formatProductData from '../transformers/product-transformer';

export class ProductRecommendationService {
  constructor(storefront) {
    this.storefront = storefront;
  }

  async getRecommendedProducts(productId) {
    let products = [];
    if (!productId) {
      return;
    }

    const variables = {
      productId,
      intent: 'RELATED',
    };
    const result = await this.storefront.query(RECOMMEND_PRODUCT_QUERY, variables);
    const { productRecommendations } = result.data;
    products = productRecommendations.map(formatProductData);
    return products;
  }
}
